def kruskal(vertices, edges):
    parent = {v: v for v in vertices}
    def find(v):
        if parent[v] != v:
            parent[v] = find(parent[v])
        return parent[v]
    def union(v1, v2):
        parent[find(v1)] = find(v2)
    edges.sort(key=lambda x: x[2])
    mst = []
    for u, v, w in edges:
        if find(u) != find(v):
            union(u, v)
            mst.append((u, v, w))
    return sum(w for _, _, w in mst)
