def prim(graph, start):
    import heapq
    visited = set()
    mst_cost = 0
    pq = [(0, start)]
    while pq:
        weight, node = heapq.heappop(pq)
        if node in visited:
            continue
        visited.add(node)
        mst_cost += weight
        for neighbor, w in graph[node]:
            if neighbor not in visited:
                heapq.heappush(pq, (w, neighbor))
    return mst_cost
