from collections import deque
def sliding_window_max(arr, k):
    dq = deque()
    res = []
    for i in range(len(arr)):
        if dq and dq[0] <= i - k:
            dq.popleft()
        while dq and arr[dq[-1]] < arr[i]:
            dq.pop()
        dq.append(i)
        if i >= k - 1:
            res.append(arr[dq[0]])
    return res
