def kosaraju_scc(graph):
    def dfs(node, visited, stack):
        visited.add(node)
        for neighbor in graph.get(node, []):
            if neighbor not in visited:
                dfs(neighbor, visited, stack)
        stack.append(node)
    def reverse_graph(graph):
        rev = {}
        for u in graph:
            for v in graph[u]:
                if v not in rev:
                    rev[v] = []
                rev[v].append(u)
        return rev
    stack = []
    visited = set()
    for node in graph:
        if node not in visited:
            dfs(node, visited, stack)
    rev = reverse_graph(graph)
    visited.clear()
    scc_count = 0
    while stack:
        node = stack.pop()
        if node not in visited:
            dfs(node, visited, [])
            scc_count += 1
    return scc_count
