def max_flow_bfs(graph, source, sink, parent):
    visited = set([source])
    q = [source]
    while q:
        u = q.pop(0)
        for v, cap in graph[u].items():
            if v not in visited and cap > 0:
                q.append(v)
                visited.add(v)
                parent[v] = u
                if v == sink:
                    return True
    return False
def ford_fulkerson(graph, source, sink):
    parent = {}
    max_flow = 0
    while max_flow_bfs(graph, source, sink, parent):
        path_flow = float('inf')
        s = sink
        while s != source:
            path_flow = min(path_flow, graph[parent[s]][s])
            s = parent[s]
        max_flow += path_flow
        v = sink
        while v != source:
            u = parent[v]
            graph[u][v] -= path_flow
            graph[v][u] = graph.get(v, {}).get(u, 0) + path_flow
            v = parent[v]
    return max_flow
