def traveling_salesman(graph, start):
    n = len(graph)
    all_visited = (1 << n) - 1
    memo = {}
    def tsp(pos, mask):
        if mask == all_visited:
            return graph[pos][start] if graph[pos][start] > 0 else float('inf')
        if (pos, mask) in memo:
            return memo[(pos, mask)]
        ans = float('inf')
        for city in range(n):
            if not mask & (1 << city) and graph[pos][city]:
                ans = min(ans, graph[pos][city] + tsp(city, mask | (1 << city)))
        memo[(pos, mask)] = ans
        return ans
    return tsp(start, 1 << start)
