class BlockCutTree:
    def __init__(self):
        self.time = 0
    def find_biconnected(self, graph):
        n = len(graph)
        disc = [-1] * n
        low = [-1] * n
        stack = []
        components = []
        def dfs(u, parent):
            nonlocal components
            disc[u] = low[u] = self.time
            self.time += 1
            children = 0
            for v in graph[u]:
                if disc[v] == -1:
                    children += 1
                    stack.append((u, v))
                    dfs(v, u)
                    low[u] = min(low[u], low[v])
                    if (parent == -1 and children > 1) or (parent != -1 and low[v] >= disc[u]):
                        comp = []
                        while stack and stack[-1] != (u, v):
                            comp.append(stack.pop())
                        comp.append(stack.pop())
                        components.append(comp)
                elif v != parent and disc[v] < disc[u]:
                    low[u] = min(low[u], disc[v])
                    stack.append((u, v))
        for i in range(n):
            if disc[i] == -1:
                dfs(i, -1)
                if stack:
                    components.append(stack[:])
                    stack.clear()
        return len(components)
