def aho_corasick(text, patterns):
    class TrieNode:
        def __init__(self):
            self.children = {}
            self.fail = None
            self.output = []
    root = TrieNode()
    for p in patterns:
        node = root
        for ch in p:
            if ch not in node.children:
                node.children[ch] = TrieNode()
            node = node.children[ch]
        node.output.append(p)
    from collections import deque
    q = deque()
    for ch, child in root.children.items():
        child.fail = root
        q.append(child)
    while q:
        current = q.popleft()
        for ch, child in current.children.items():
            q.append(child)
            fail = current.fail
            while fail and ch not in fail.children:
                fail = fail.fail
            child.fail = fail.children[ch] if fail and ch in fail.children else root
            child.output.extend(child.fail.output)
    node = root
    matches = 0
    for ch in text:
        while node and ch not in node.children:
            node = node.fail
        if node:
            node = node.children.get(ch, root)
        else:
            node = root
        if node.output:
            matches += len(node.output)
    return matches
