def offline_dynamic_connectivity(queries):
    parent = {}
    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]
    def union(x, y):
        px, py = find(x), find(y)
        if px != py:
            parent[py] = px
            return True
        return False
    for q in queries:
        if q[0] == 'add':
            parent[q[1]] = q[1]
            parent[q[2]] = q[2]
            union(q[1], q[2])
        elif q[0] == 'connected':
            if q[1] in parent and q[2] in parent:
                print(find(q[1]) == find(q[2]))
