class ConvexHullTrick:
    def __init__(self):
        self.lines = []
        self.points = []
    def intersect_x(self, l1, l2):
        m1, b1 = l1
        m2, b2 = l2
        return (b2 - b1) / (m1 - m2)
    def add_line(self, m, b):
        new_line = (m, b)
        while len(self.lines) >= 2:
            x1 = self.intersect_x(self.lines[-2], self.lines[-1])
            x2 = self.intersect_x(self.lines[-1], new_line)
            if x1 < x2:
                break
            self.lines.pop()
        self.lines.append(new_line)
    def query(self, x):
        lo, hi = 0, len(self.lines) - 1
        while lo < hi:
            mid = (lo + hi) // 2
            if self.intersect_x(self.lines[mid], self.lines[mid+1]) < x:
                lo = mid + 1
            else:
                hi = mid
        m, b = self.lines[lo]
        return m * x + b
