class AhoCorasickAutomaton:
    def __init__(self):
        self.trie = [{}]
        self.fail = [0]
        self.output = [[]]
    def add_pattern(self, pattern, idx):
        node = 0
        for ch in pattern:
            if ch not in self.trie[node]:
                self.trie[node][ch] = len(self.trie)
                self.trie.append({})
                self.fail.append(0)
                self.output.append([])
            node = self.trie[node][ch]
        self.output[node].append(idx)
    def build(self):
        from collections import deque
        q = deque()
        for ch, nxt in self.trie[0].items():
            self.fail[nxt] = 0
            q.append(nxt)
        while q:
            r = q.popleft()
            for ch, nxt in self.trie[r].items():
                q.append(nxt)
                f = self.fail[r]
                while f and ch not in self.trie[f]:
                    f = self.fail[f]
                self.fail[nxt] = self.trie[f].get(ch, 0)
                self.output[nxt].extend(self.output[self.fail[nxt]])
    def search(self, text):
        node = 0
        count = 0
        for ch in text:
            while node and ch not in self.trie[node]:
                node = self.fail[node]
            node = self.trie[node].get(ch, 0)
            if self.output[node]:
                count += len(self.output[node])
        return count
