class PalindromicTree:
    def __init__(self, s):
        self.s = s
        self.n = len(s)
        self.tree = [{'len': -1, 'link': 0, 'next': {}}, {'len': 0, 'link': 0, 'next': {}}]
        self.last = 1
        for i, ch in enumerate(s):
            self.add_char(i)
    def get_link(self, node, pos):
        while True:
            cur_len = self.tree[node]['len']
            if pos - 1 - cur_len >= 0 and self.s[pos - 1 - cur_len] == self.s[pos]:
                break
            node = self.tree[node]['link']
        return node
    def add_char(self, pos):
        cur = self.get_link(self.last, pos)
        ch = self.s[pos]
        if ch not in self.tree[cur]['next']:
            new_node = len(self.tree)
            self.tree.append({'len': self.tree[cur]['len'] + 2, 'link': 0, 'next': {}})
            if self.tree[new_node]['len'] == 1:
                self.tree[new_node]['link'] = 1
            else:
                link_node = self.get_link(self.tree[cur]['link'], pos)
                self.tree[new_node]['link'] = self.tree[link_node]['next'][ch]
            self.tree[cur]['next'][ch] = new_node
        self.last = self.tree[cur]['next'][ch]
    def count_palindromes(self):
        return len(self.tree) - 2
