class SegmentTreeBeats:
    def __init__(self, arr):
        self.n = len(arr)
        self.max1 = [0] * (4 * self.n)
        self.max2 = [float('-inf')] * (4 * self.n)
        self.max_cnt = [0] * (4 * self.n)
        self.sum = [0] * (4 * self.n)
        self.build(arr, 0, 0, self.n - 1)
    def merge(self, node, left, right):
        if self.max1[left] > self.max1[right]:
            self.max1[node] = self.max1[left]
            self.max_cnt[node] = self.max_cnt[left]
            self.max2[node] = max(self.max2[left], self.max1[right])
        elif self.max1[left] < self.max1[right]:
            self.max1[node] = self.max1[right]
            self.max_cnt[node] = self.max_cnt[right]
            self.max2[node] = max(self.max1[left], self.max2[right])
        else:
            self.max1[node] = self.max1[left]
            self.max_cnt[node] = self.max_cnt[left] + self.max_cnt[right]
            self.max2[node] = max(self.max2[left], self.max2[right])
        self.sum[node] = self.sum[left] + self.sum[right]
    def build(self, arr, node, l, r):
        if l == r:
            self.max1[node] = self.sum[node] = arr[l]
            self.max2[node] = float('-inf')
            self.max_cnt[node] = 1
        else:
            mid = (l + r) // 2
            self.build(arr, 2*node+1, l, mid)
            self.build(arr, 2*node+2, mid+1, r)
            self.merge(node, 2*node+1, 2*node+2)
    def query_sum(self, node, l, r, ql, qr):
        if ql > r or qr < l:
            return 0
        if ql <= l and r <= qr:
            return self.sum[node]
        mid = (l + r) // 2
        return self.query_sum(2*node+1, l, mid, ql, qr) + self.query_sum(2*node+2, mid+1, r, ql, qr)
