class ImplicitTreap:
    def __init__(self, val):
        self.val = val
        self.priority = (id(self) * 2654435761) % (2**31)
        self.left = None
        self.right = None
        self.size = 1
    def update_size(self):
        self.size = 1
        if self.left:
            self.size += self.left.size
        if self.right:
            self.size += self.right.size
    def split(self, k):
        left_size = self.left.size if self.left else 0
        if k <= left_size:
            left, right = self.left.split(k) if self.left else (None, self.left)
            self.left = right
            self.update_size()
            return left, self
        else:
            left, right = self.right.split(k - left_size - 1) if self.right else (self.right, None)
            self.right = left
            self.update_size()
            return self, right
    @staticmethod
    def merge(left, right):
        if not left or not right:
            return left or right
        if left.priority > right.priority:
            left.right = ImplicitTreap.merge(left.right, right)
            left.update_size()
            return left
        else:
            right.left = ImplicitTreap.merge(left, right.left)
            right.update_size()
            return right
    def inorder(self):
        res = []
        if self.left:
            res.extend(self.left.inorder())
        res.append(self.val)
        if self.right:
            res.extend(self.right.inorder())
        return res
