class CountMinSketch:
    def __init__(self, width, depth):
        self.width = width
        self.depth = depth
        self.table = [[0] * width for _ in range(depth)]
    def add(self, item, count=1):
        s = str(item)
        for i in range(self.depth):
            h = hash(s + str(i)) % self.width
            self.table[i][abs(h)] += count
    def estimate(self, item):
        s = str(item)
        return min(self.table[i][abs(hash(s + str(i))) % self.width] for i in range(self.depth))
