class PersistentSegmentTree:
    def __init__(self, arr):
        self.n = len(arr)
        self.roots = []
        self.roots.append(self.build(arr, 0, self.n - 1))
    def build(self, arr, l, r):
        node = {'val': 0, 'left': None, 'right': None}
        if l == r:
            node['val'] = arr[l]
        else:
            mid = (l + r) // 2
            node['left'] = self.build(arr, l, mid)
            node['right'] = self.build(arr, mid + 1, r)
            node['val'] = (node['left']['val'] if node['left'] else 0) + (node['right']['val'] if node['right'] else 0)
        return node
    def update(self, prev_node, l, r, idx, val):
        node = {'val': 0, 'left': None, 'right': None}
        if l == r:
            node['val'] = val
        else:
            mid = (l + r) // 2
            if idx <= mid:
                node['left'] = self.update(prev_node['left'] if prev_node else None, l, mid, idx, val)
                node['right'] = prev_node['right'] if prev_node else None
            else:
                node['left'] = prev_node['left'] if prev_node else None
                node['right'] = self.update(prev_node['right'] if prev_node else None, mid + 1, r, idx, val)
            node['val'] = (node['left']['val'] if node['left'] else 0) + (node['right']['val'] if node['right'] else 0)
        return node
    def add_version(self, idx, val):
        self.roots.append(self.update(self.roots[-1], 0, self.n - 1, idx, val))
    def query(self, node, l, r, ql, qr):
        if not node or ql > r or qr < l:
            return 0
        if ql <= l and r <= qr:
            return node['val']
        mid = (l + r) // 2
        return self.query(node['left'], l, mid, ql, qr) + self.query(node['right'], mid + 1, r, ql, qr)
