def hungarian_algorithm(cost_matrix):
    n, m = len(cost_matrix), len(cost_matrix[0])
    u = [0] * (n + 1)
    v = [0] * (m + 1)
    p = [0] * (m + 1)
    way = [0] * (m + 1)
    for i in range(1, n + 1):
        p[0] = i
        j0 = 0
        minv = [float('inf')] * (m + 1)
        used = [False] * (m + 1)
        while True:
            used[j0] = True
            i0 = p[j0]
            delta = float('inf')
            j1 = 0
            for j in range(1, m + 1):
                if not used[j]:
                    cur = cost_matrix[i0-1][j-1] - u[i0] - v[j]
                    if cur < minv[j]:
                        minv[j] = cur
                        way[j] = j0
                    if minv[j] < delta:
                        delta = minv[j]
                        j1 = j
            for j in range(m + 1):
                if used[j]:
                    u[p[j]] += delta
                    v[j] -= delta
                else:
                    minv[j] -= delta
            j0 = j1
            if p[j0] == 0:
                break
        while True:
            j1 = way[j0]
            p[j0] = p[j1]
            j0 = j1
            if j0 == 0:
                break
    return -v[0]
cost = [[2, 3, 1], [5, 4, 8], [5, 6, 6]]
print(hungarian_algorithm(cost))

class XFastTrie:
    def __init__(self, universe_size):
        self.u = universe_size
        self.w = universe_size.bit_length()
        self.layers = [{} for _ in range(self.w + 1)]
    def insert(self, x):
        for i in range(self.w + 1):
            prefix = x >> (self.w - i) if i > 0 else 0
            if prefix not in self.layers[i]:
                self.layers[i][prefix] = set()
            self.layers[i][prefix].add(x)
    def find(self, x):
        for i in range(self.w + 1):
            prefix = x >> (self.w - i) if i > 0 else 0
            if prefix in self.layers[i]:
                return x in self.layers[i][prefix]
        return False
