class BoyerMoore:
    def __init__(self, pattern):
        self.pattern = pattern
        self.bad_char = {}
        for i, ch in enumerate(pattern):
            self.bad_char[ch] = i
    def search(self, text):
        m, n = len(self.pattern), len(text)
        if m == 0:
            return 0
        i = 0
        while i <= n - m:
            j = m - 1
            while j >= 0 and self.pattern[j] == text[i + j]:
                j -= 1
            if j < 0:
                return i
            else:
                bc = self.bad_char.get(text[i + j], -1)
                i += max(1, j - bc)
        return -1
