class SuffixTree:
    def __init__(self, s):
        self.s = s + '$'
        self.n = len(self.s)
        self.tree = {}
        self.build()
    def build(self):
        for i in range(self.n):
            self.add_suffix(i)
    def add_suffix(self, start):
        node = 0
        pos = start
        while pos < self.n:
            ch = self.s[pos]
            if ch not in self.tree.get(node, {}):
                if node not in self.tree:
                    self.tree[node] = {}
                self.tree[node][ch] = (pos, self.n)
                break
            else:
                edge_start, edge_end = self.tree[node][ch]
                k = 0
                while k < edge_end - edge_start and pos + k < self.n and self.s[edge_start + k] == self.s[pos + k]:
                    k += 1
                if pos + k == self.n or k == edge_end - edge_start:
                    pos += k
                    node = hash((node, self.tree[node][ch]))
                else:
                    new_node = hash((node, ch, 'split'))
                    self.tree[new_node] = {self.s[edge_start + k]: (edge_start + k, edge_end)}
                    self.tree[node][ch] = (edge_start, edge_start + k)
                    self.tree[new_node][self.s[pos + k]] = (pos + k, self.n)
                    if node not in self.tree:
                        self.tree[node] = {}
                    break
    def count_leaves(self):
        count = 0
        def dfs(node):
            nonlocal count
            if node not in self.tree or not self.tree[node]:
                count += 1
                return
            for ch, (start, end) in self.tree[node].items():
                dfs(hash((node, (start, end))))
        dfs(0)
        return count
