print(st.count_leaves())

def fft_convolution_mod(a, b, mod=998244353):
    def ntt(a, invert):
        n = len(a)
        j = 0
        for i in range(1, n):
            bit = n >> 1
            while j & bit:
                j ^= bit
                bit >>= 1
            j ^= bit
            if i < j:
                a[i], a[j] = a[j], a[i]
        length = 2
        while length <= n:
            wlen = pow(3, (mod - 1) // length, mod)
            if invert:
                wlen = pow(wlen, mod - 2, mod)
            for i in range(0, n, length):
                w = 1
                for j in range(i, i + length // 2):
                    u = a[j]
                    v = a[j + length // 2] * w % mod
                    a[j] = (u + v) % mod
                    a[j + length // 2] = (u - v + mod) % mod
                    w = w * wlen % mod
            length <<= 1
        if invert:
            inv_n = pow(n, mod - 2, mod)
            for i in range(n):
                a[i] = a[i] * inv_n % mod
    n = 1
    while n < len(a) + len(b) - 1:
        n <<= 1
    fa = a + [0] * (n - len(a))
    fb = b + [0] * (n - len(b))
    ntt(fa, False)
    ntt(fb, False)
    for i in range(n):
        fa[i] = fa[i] * fb[i] % mod
    ntt(fa, True)
    return fa[:len(a)+len(b)-1]
print(fft_convolution_mod([1, 2, 3], [4, 5, 6]))

class RandomizedMeldableHeap:
    def __init__(self, val=None):
        self.val = val
        self.left = None
        self.right = None
    @staticmethod
    def merge(h1, h2):
        if not h1:
            return h2
        if not h2:
            return h1
        import random
        if h1.val > h2.val:
            h1, h2 = h2, h1
        if random.random() < 0.5:
            h1.left = RandomizedMeldableHeap.merge(h1.left, h2)
        else:
            h1.right = RandomizedMeldableHeap.merge(h1.right, h2)
        return h1
    @staticmethod
    def pop_min(h):
        if not h:
            return None, None
        return h.val, RandomizedMeldableHeap.merge(h.left, h.right)
    @staticmethod
    def size(h):
        if not h:
            return 0
        return 1 + RandomizedMeldableHeap.size(h.left) + RandomizedMeldableHeap.size(h.right)
