class BTree:
    def __init__(self, t):
        self.t = t
        self.root = BTreeNode(t, True)
    def insert(self, k):
        root = self.root
        if len(root.keys) == 2 * self.t - 1:
            new_root = BTreeNode(self.t, False)
            new_root.children.append(self.root)
            new_root.split_child(0, self.root)
            self.root = new_root
        self.root.insert_non_full(k)
    def search(self, k):
        return self.root.search(k)
class BTreeNode:
    def __init__(self, t, leaf):
        self.t = t
        self.leaf = leaf
        self.keys = []
        self.children = []
    def split_child(self, i, y):
        z = BTreeNode(self.t, y.leaf)
        z.keys = y.keys[self.t:]
        y.keys = y.keys[:self.t-1]
        if not y.leaf:
            z.children = y.children[self.t:]
            y.children = y.children[:self.t]
        self.children.insert(i + 1, z)
        self.keys.insert(i, y.keys.pop())
    def insert_non_full(self, k):
        i = len(self.keys) - 1
        if self.leaf:
            self.keys.append(None)
            while i >= 0 and k < self.keys[i]:
                self.keys[i + 1] = self.keys[i]
                i -= 1
            self.keys[i + 1] = k
        else:
            while i >= 0 and k < self.keys[i]:
                i -= 1
            i += 1
            if len(self.children[i].keys) == 2 * self.t - 1:
                self.split_child(i, self.children[i])
                if k > self.keys[i]:
                    i += 1
            self.children[i].insert_non_full(k)
    def search(self, k):
        i = 0
        while i < len(self.keys) and k > self.keys[i]:
            i += 1
        if i < len(self.keys) and k == self.keys[i]:
            return True
        if self.leaf:
            return False
        return self.children[i].search(k)
