class Rope:
    class Node:
        def __init__(self, s):
            self.s = s
            self.left = None
            self.right = None
            self.weight = len(s)
    def __init__(self, s=''):
        self.root = Rope.Node(s) if s else None
    def concat(self, other):
        if not self.root:
            return other.root
        if not other.root:
            return self.root
        new_root = Rope.Node('')
        new_root.left = self.root
        new_root.right = other.root
        new_root.weight = self.get_weight(self.root)
        return new_root
    def get_weight(self, node):
        if not node:
            return 0
        if node.left is None and node.right is None:
            return node.weight
        return self.get_weight(node.left)
    def traverse(self, node, result):
        if not node:
            return
        if node.left is None and node.right is None:
            result.append(node.s)
        else:
            self.traverse(node.left, result)
            self.traverse(node.right, result)
    def to_string(self):
        result = []
        self.traverse(self.root, result)
        return ''.join(result)
