class FusionTree:
    class Node:
        def __init__(self, k):
            self.keys = sorted(k)
            self.children = []
            self.b = len(k) ** 0.5 if k else 0
    def __init__(self, universe):
        self.u = universe
        self.root = None
    def insert(self, x):
        if not self.root:
            self.root = FusionTree.Node([x])
        else:
            self._insert(self.root, x)
    def _insert(self, node, x):
        node.keys.append(x)
        node.keys.sort()
    def predecessor(self, x):
        def find_pred(node, x):
            if not node:
                return None
            for i in range(len(node.keys) - 1, -1, -1):
                if node.keys[i] <= x:
                    return node.keys[i]
            return None
        return find_pred(self.root, x)
