class CountMinSketchHeavyHitters:
    def __init__(self, width, depth, k):
        self.cms = [[0]*width for _ in range(depth)]
        self.width = width
        self.depth = depth
        self.k = k
        self.heap = []
    def add(self, item, count=1):
        s = str(item)
        for i in range(self.depth):
            h = abs(hash(s + str(i))) % self.width
            self.cms[i][h] += count
    def estimate(self, item):
        s = str(item)
        return min(self.cms[i][abs(hash(s + str(i))) % self.width] for i in range(self.depth))
    def get_heavy_hitters(self, items):
        import heapq
        for item in set(items):
            freq = self.estimate(item)
            if len(self.heap) < self.k:
                heapq.heappush(self.heap, (freq, item))
            elif freq > self.heap[0][0]:
                heapq.heapreplace(self.heap, (freq, item))
        return [item for _, item in sorted(self.heap, reverse=True)]
cms = CountMinSketchHeavyHitters(50, 5, 2)
