class HopcroftKarp:
    def __init__(self, n_left, n_right):
        self.n_left = n_left
        self.n_right = n_right
        self.adj = [[] for _ in range(n_left)]
    def add_edge(self, u, v):
        self.adj[u].append(v)
    def match(self):
        pair_u = [-1] * self.n_left
        pair_v = [-1] * self.n_right
        dist = [0] * self.n_left
        def bfs():
            from collections import deque
            q = deque()
            for u in range(self.n_left):
                if pair_u[u] == -1:
                    dist[u] = 0
                    q.append(u)
                else:
                    dist[u] = float('inf')
            found = False
            while q:
                u = q.popleft()
                for v in self.adj[u]:
                    if pair_v[v] == -1:
                        found = True
                    elif dist[pair_v[v]] == float('inf'):
                        dist[pair_v[v]] = dist[u] + 1
                        q.append(pair_v[v])
            return found
        def dfs(u):
            for v in self.adj[u]:
                if pair_v[v] == -1 or (dist[pair_v[v]] == dist[u] + 1 and dfs(pair_v[v])):
                    pair_u[u] = v
                    pair_v[v] = u
                    return True
            dist[u] = float('inf')
            return False
        matching = 0
        while bfs():
            for u in range(self.n_left):
                if pair_u[u] == -1 and dfs(u):
                    matching += 1
        return matching
