class VanEmdeBoas:
    def __init__(self, u):
        self.u = u
        self.min_val = -1
        self.max_val = -1
        if u > 2:
            self.sqrt_u = 1 << ((u.bit_length() - 1) // 2)
            self.summary = VanEmdeBoas(self.upper_sqrt())
            self.cluster = [None] * self.upper_sqrt()
    def upper_sqrt(self):
        return 1 << ((self.u.bit_length() + 1) // 2)
    def lower_sqrt(self):
        return 1 << (self.u.bit_length() // 2)
    def high(self, x):
        return x // self.lower_sqrt()
    def low(self, x):
        return x % self.lower_sqrt()
    def index(self, h, l):
        return h * self.lower_sqrt() + l
    def is_empty(self):
        return self.min_val == -1
    def insert(self, x):
        if self.is_empty():
            self.min_val = self.max_val = x
            return
        if x < self.min_val:
            x, self.min_val = self.min_val, x
        if x > self.max_val:
            self.max_val = x
        if self.u > 2:
            high = self.high(x)
            low = self.low(x)
            if self.cluster[high] is None:
                self.cluster[high] = VanEmdeBoas(self.lower_sqrt())
            if self.cluster[high].is_empty():
                self.summary.insert(high)
            self.cluster[high].insert(low)
    def member(self, x):
        if self.is_empty():
            return False
        if x == self.min_val or x == self.max_val:
            return True
        if self.u == 2:
            return False
        high = self.high(x)
        low = self.low(x)
        if self.cluster[high] is None:
            return False
        return self.cluster[high].member(low)
