def berlekamp_massey(s):
    n = len(s)
    C = [1]
    B = [1]
    L = 0
    m = 1
    b = 1
    for i in range(n):
        d = s[i]
        for j in range(1, L + 1):
            if j < len(C):
                d ^= C[j] & s[i - j]
        if d == 1:
            T = C[:]
            coef = [0] * (i - m + len(B))
            for j in range(len(B)):
                coef[i - m + j] = B[j]
            for j in range(len(coef)):
                if j < len(C):
                    C[j] ^= coef[j]
                else:
                    C.append(coef[j])
            if 2 * L <= i:
                L = i + 1 - L
                B = T
                m = i
                b = d
    return L
