class RangeTree2D:
    def __init__(self, points):
        self.points = sorted(points)
        self.n = len(self.points)
        self.tree = [[]] * (4 * self.n)
        self.build(0, 0, self.n - 1)
    def build(self, node, l, r):
        if l == r:
            self.tree[node] = [self.points[l][1]]
        else:
            mid = (l + r) // 2
            self.build(2*node+1, l, mid)
            self.build(2*node+2, mid+1, r)
            self.tree[node] = sorted(self.tree[2*node+1] + self.tree[2*node+2])
    def query(self, x1, x2, y1, y2):
        import bisect
        def query_node(node, l, r):
            if self.points[r][0] < x1 or self.points[l][0] > x2:
                return 0
            if x1 <= self.points[l][0] and self.points[r][0] <= x2:
                return bisect.bisect_right(self.tree[node], y2) - bisect.bisect_left(self.tree[node], y1)
            mid = (l + r) // 2
            return query_node(2*node+1, l, mid) + query_node(2*node+2, mid+1, r)
        return query_node(0, 0, self.n - 1)
