class ImplicitTreapArray:
    class Node:
        def __init__(self, val):
            self.val = val
            self.prio = hash(str(val)) ^ hash(id(self))
            self.left = None
            self.right = None
            self.sz = 1
    def __init__(self):
        self.root = None
    def sz(self, node):
        return node.sz if node else 0
    def upd(self, node):
        if node:
            node.sz = 1 + self.sz(node.left) + self.sz(node.right)
    def split(self, node, k):
        if not node:
            return None, None
        if self.sz(node.left) >= k:
            left, right = self.split(node.left, k)
            node.left = right
            self.upd(node)
            return left, node
        else:
            left, right = self.split(node.right, k - self.sz(node.left) - 1)
            node.right = left
            self.upd(node)
            return node, right
    def merge(self, left, right):
        if not left or not right:
            return left or right
        if left.prio > right.prio:
            left.right = self.merge(left.right, right)
            self.upd(left)
            return left
        else:
            right.left = self.merge(left, right.left)
            self.upd(right)
            return right
    def insert(self, pos, val):
        left, right = self.split(self.root, pos)
        new_node = ImplicitTreapArray.Node(val)
        self.root = self.merge(self.merge(left, new_node), right)
    def get(self, pos):
        def _get(node, pos):
            left_sz = self.sz(node.left)
            if pos < left_sz:
                return _get(node.left, pos)
            elif pos == left_sz:
                return node.val
            else:
                return _get(node.right, pos - left_sz - 1)
        return _get(self.root, pos)
