def waldo_suffix_automaton_match(s, patterns):
    class SAM:
        def __init__(self, s):
            self.len = [0]
            self.link = [-1]
            self.next = [{}]
            self.last = 0
            for ch in s:
                self.extend(ch)
        def extend(self, c):
            cur = len(self.len)
            self.len.append(self.len[self.last] + 1)
            self.link.append(0)
            self.next.append({})
            p = self.last
            while p != -1 and c not in self.next[p]:
                self.next[p][c] = cur
                p = self.link[p]
            if p == -1:
                self.link[cur] = 0
            else:
                q = self.next[p][c]
                if self.len[p] + 1 == self.len[q]:
                    self.link[cur] = q
                else:
                    clone = len(self.len)
                    self.len.append(self.len[p] + 1)
                    self.link.append(self.link[q])
                    self.next.append(self.next[q].copy())
                    while p != -1 and self.next[p].get(c) == q:
                        self.next[p][c] = clone
                        p = self.link[p]
                    self.link[q] = self.link[cur] = clone
            self.last = cur
        def contains(self, pattern):
            node = 0
            for ch in pattern:
                if ch not in self.next[node]:
                    return False
                node = self.next[node][ch]
            return True
    sam = SAM(s)
    return sum(1 for p in patterns if sam.contains(p))
