class PairingHeap:
    class Node:
        def __init__(self, key):
            self.key = key
            self.child = None
            self.sibling = None
            self.prev = None
    def __init__(self):
        self.root = None
    def merge(self, h1, h2):
        if not h1:
            return h2
        if not h2:
            return h1
        if h1.key > h2.key:
            h1, h2 = h2, h1
        h2.prev = h1
        h2.sibling = h1.child
        if h1.child:
            h1.child.prev = h2
        h1.child = h2
        return h1
    def insert(self, key):
        node = PairingHeap.Node(key)
        self.root = self.merge(self.root, node)
    def delete_min(self):
        if not self.root:
            return None
        min_key = self.root.key
        if self.root.child:
            children = []
            curr = self.root.child
            while curr:
                next_curr = curr.sibling
                curr.sibling = None
                curr.prev = None
                children.append(curr)
                curr = next_curr
            while len(children) > 1:
                a = children.pop()
                b = children.pop()
                children.append(self.merge(a, b))
            self.root = children[0] if children else None
        else:
            self.root = None
        return min_key
    def size(self):
        def count(node):
            if not node:
                return 0
            return 1 + count(node.child) + count(node.sibling)
        return count(self.root)
