class SplayTreeArray:
    class Node:
        def __init__(self, val):
            self.val = val
            self.left = None
            self.right = None
            self.parent = None
            self.sz = 1
    def __init__(self):
        self.root = None
    def size(self, node):
        return node.sz if node else 0
    def update(self, node):
        if node:
            node.sz = 1 + self.size(node.left) + self.size(node.right)
    def rotate(self, x):
        p = x.parent
        g = p.parent
        if p.left == x:
            p.left = x.right
            if x.right:
                x.right.parent = p
            x.right = p
        else:
            p.right = x.left
            if x.left:
                x.left.parent = p
            x.left = p
        p.parent = x
        x.parent = g
        if g:
            if g.left == p:
                g.left = x
            else:
                g.right = x
        self.update(p)
        self.update(x)
    def splay(self, x):
        while x.parent:
            p = x.parent
            g = p.parent
            if g:
                if (p.left == x) == (g.left == p):
                    self.rotate(p)
                else:
                    self.rotate(x)
            self.rotate(x)
        self.root = x
    def kth(self, k):
        if not self.root or k < 0 or k >= self.size(self.root):
            return None
        curr = self.root
        while curr:
            left_sz = self.size(curr.left)
            if k < left_sz:
                curr = curr.left
            elif k == left_sz:
                return curr.val
            else:
                k -= left_sz + 1
                curr = curr.right
        return None
    def insert(self, val, pos):
        new_node = SplayTreeArray.Node(val)
        if not self.root:
            self.root = new_node
            return
        curr = self.root
        while True:
            left_sz = self.size(curr.left)
            if pos <= left_sz:
                if not curr.left:
                    curr.left = new_node
                    new_node.parent = curr
                    break
                curr = curr.left
            else:
                pos -= left_sz + 1
                if not curr.right:
                    curr.right = new_node
                    new_node.parent = curr
                    break
                curr = curr.right
        self.splay(new_node)
