def burnikel_ziegler_division(a, b):
    if b == 0:
        raise ValueError('Division by zero')
    if a < b:
        return 0, a
    q = 0
    r = a
    while r >= b:
        k = r.bit_length() - b.bit_length()
        if k < 0:
            k = 0
        trial = b << k
        if trial <= r:
            r -= trial
            q += 1 << k
        else:
            trial = b << (k - 1)
            r -= trial
            q += 1 << (k - 1)
    return q, r
