def gusfield_z_algorithm(text, pattern):
    concat = pattern + '#' + text
    n = len(concat)
    z = [0] * n
    l = r = 0
    for i in range(1, n):
        if i <= r:
            z[i] = min(r - i + 1, z[i - l])
        while i + z[i] < n and concat[z[i]] == concat[i + z[i]]:
            z[i] += 1
        if i + z[i] - 1 > r:
            l, r = i, i + z[i] - 1
    matches = []
    for i in range(len(pattern) + 1, n):
        if z[i] == len(pattern):
            matches.append(i - len(pattern) - 1)
    return len(matches)
print(gusfield_z_algorithm('AABAACAADAABAAABAA', 'AABA'))
